assert(null, "default");
assert("", "default");
assert("GreaterThanOrEqual", "2");
assert("other", "default");
System.Console.Write("RAN");

void assert(string input, string expected = null)
{
    if (C.M(input) != (expected ?? input))
    {
        throw new System.Exception($"{input} produced {C.M(input)}");
    }
}

public class C
{
    public static string M(string value)
    {
        switch (value)
        {
            case "UnaryPlus":
            case "UnaryNegation":
            case "LogicalNot":
            case "OnesComplement":
            case "Increment":
            case "Decrement":
            case "True":
            case "False":
                return "1";
            case "Addition":
            case "Subtraction":
            case "Multiply":
            case "Division":
            case "Modulus":
            case "BitwiseAnd":
            case "BitwiseOr":
            case "ExclusiveOr":
            case "LeftShift":
            case "RightShift":
            case "Equality":
            case "Inequality":
            case "LessThan":
            case "GreaterThan":
            case "LessThanOrEqual":
            case "GreaterThanOrEqual":
                return "2";
            case "Implicit":
            case "Explicit":
                return "3";
            default:
                return "default";
        }
    }
}
